<script setup>
// Directorio institucional exclusivo para emprendedores.
import { ref, computed, onMounted } from "vue";
import { useRouter } from "vue-router";
import { supabase } from "../../lib/supabaseClient";
import BusinessNav from "../../components/business/BusinessNav.vue";
const router=useRouter(); const businessName=ref("Thrive"); const institutions=ref([]); const loading=ref(true); const errorText=ref(""); const search=ref(""); const department=ref("Todos");
const departments=computed(()=>["Todos",...Array.from(new Set(institutions.value.map(i=>i.department).filter(Boolean))).sort((a,b)=>a.localeCompare(b,"es"))]);
const filtered=computed(()=>{const q=search.value.toLowerCase().trim();return institutions.value.filter(i=>(department.value==="Todos"||i.department===department.value)&&(!q||[i.name,i.description,i.department,i.district].join(" ").toLowerCase().includes(q)));});
function initials(name){return String(name||"TH").trim().split(/\s+/).slice(0,2).map(w=>w[0]?.toUpperCase()).join("");}
function url(value){if(!value)return"";return /^https?:\/\//i.test(value)?value:`https://${value}`;}
function whatsapp(phone,name){const raw=String(phone||"").replace(/\D/g,"");const finalPhone=raw.length===8?`503${raw}`:raw;const msg=encodeURIComponent(`Hola, encontré a ${name} por medio de Thrive y quisiera obtener más información.`);window.open(finalPhone?`https://wa.me/${finalPhone}?text=${msg}`:`https://wa.me/?text=${msg}`,"_blank","noopener,noreferrer");}
async function load(){loading.value=true;errorText.value="";try{const{data:{user}}=await supabase.auth.getUser();if(!user)return router.replace({name:"Access"});const[{data:b,error:bErr},{data,error}]=await Promise.all([supabase.from("entrepreneurs").select("business_name").eq("id",user.id).single(),supabase.rpc("get_public_institutions")]);if(bErr)throw bErr;if(error)throw error;businessName.value=b.business_name||"Thrive";institutions.value=(data||[]).map(i=>({id:i.id,name:i.institution_name,description:i.description||"",website:i.website||"",department:i.department||"",district:i.district||"",logoUrl:i.logo_url||"",phone:i.phone||""}));}catch(e){console.error(e);errorText.value="No fue posible cargar las instituciones.";}finally{loading.value=false;}}
onMounted(load);
</script>
<template>
<div class="min-h-screen bg-[#F8FBFC] pb-[78px] text-gray-700 lg:pb-10"><BusinessNav active="institutions" :business-name="businessName"/><main class="mx-auto max-w-[1450px] px-3 py-5 sm:px-5 lg:px-8 lg:py-7"><section class="overflow-hidden rounded-[30px] bg-gradient-to-r from-[#0077B6] to-[#00B4D8] p-6 text-white shadow-[0_16px_45px_rgba(0,119,182,.18)] sm:p-8"><p class="text-xs font-black uppercase tracking-[.18em] text-white/70">Red de apoyo</p><h1 class="mt-2 text-3xl font-black sm:text-4xl">Instituciones en Thrive</h1><p class="mt-2 max-w-3xl text-sm leading-6 text-white/75">Consulta los perfiles de las instituciones que acompañan la plataforma, visita sus sitios y contáctalas directamente cuando necesites información.</p><div class="mt-5 rounded-[18px] bg-white/15 px-4 py-3 backdrop-blur"><input v-model="search" class="w-full bg-transparent text-sm font-semibold text-white outline-none placeholder:text-white/55" placeholder="Buscar institución o departamento"></div></section><div class="mt-4 flex gap-2 overflow-x-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"><button v-for="d in departments" :key="d" class="whitespace-nowrap rounded-full px-4 py-2 text-xs font-bold" :class="department===d?'bg-[#0077B6] text-white':'bg-white text-[#0077B6] ring-1 ring-[#CAF0F8]'" @click="department=d">{{ d }}</button></div><div v-if="loading" class="py-24 text-center"><div class="mx-auto h-9 w-9 animate-spin rounded-full border-4 border-[#CAF0F8] border-t-[#00B4D8]"></div></div><div v-else-if="errorText" class="mt-5 rounded-[24px] bg-white p-10 text-center shadow-sm">{{ errorText }}</div><section v-else class="mt-6 grid gap-4 md:grid-cols-2 xl:grid-cols-3"><article v-for="i in filtered" :key="i.id" class="rounded-[26px] bg-white p-5 shadow-sm ring-1 ring-gray-100"><div class="flex items-center gap-4"><img v-if="i.logoUrl" :src="i.logoUrl" class="h-18 w-18 h-[72px] w-[72px] rounded-[22px] object-cover"><div v-else class="flex h-[72px] w-[72px] items-center justify-center rounded-[22px] bg-[#EAF9FC] font-black text-[#0077B6]">{{ initials(i.name) }}</div><div class="min-w-0"><h2 class="truncate text-xl font-black text-gray-800">{{ i.name }}</h2><p class="mt-1 text-xs font-semibold text-gray-400">{{ i.district || i.department || 'El Salvador' }}</p></div></div><p class="mt-4 line-clamp-4 text-sm leading-6 text-gray-500">{{ i.description || 'Institución asociada a Thrive.' }}</p><div class="mt-5 grid grid-cols-2 gap-2"><button v-if="i.phone" class="rounded-[15px] bg-[#25D366] px-3 py-3 text-sm font-black text-white" @click="whatsapp(i.phone,i.name)">WhatsApp</button><a v-if="i.website" :href="url(i.website)" target="_blank" rel="noopener noreferrer" class="rounded-[15px] bg-[#EAF9FC] px-3 py-3 text-center text-sm font-black text-[#0077B6]">Sitio web</a><button class="col-span-2 rounded-[15px] bg-[#0077B6] px-3 py-3 text-sm font-black text-white" @click="router.push({name:'InstitutionPublic',params:{id:i.id}})">Ver perfil institucional</button></div></article></section><div v-if="!loading&&!errorText&&!filtered.length" class="mt-6 rounded-[24px] bg-white p-10 text-center text-sm text-gray-500 shadow-sm">No encontramos instituciones con esos filtros.</div></main></div>
</template>
